1	package credit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11	)
12	
13	// recordVersion 是当前记录文件格式版本。
14	const recordVersion = 1
15	
16	// fileData 是记录文件的磁盘格式。
17	type fileData struct {
18		Version       int            `json:"version"`
19		Courses       []*Course      `json:"courses"`
20		Students      []*Student     `json:"students"`
21		Requirements  []*Requirement `json:"requirements"`
22		Enrollments   []*Enrollment  `json:"enrollments"`
23		Waivers       []*Waiver      `json:"waivers"`
24		NextResultSeq int            `json:"nextResultSeq"`
25	}
26	
27	// Load 从 path 读取记录。
28	//
29	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
30	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
31	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
32	// 空文件同样视为损坏，而不是空记录。
33	//
34	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
35	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
36	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
37	// 绝不依据已读到的前半条记录继续办理业务。
38	//
39	// 同一个 JSON 对象内的字段名称也只能出现一次：无论重复的是学分、学生编号
40	// 还是其他字段，也无论两个值是否相同，整份文件都判为损坏。规则同时适用于
41	// 最外层对象与其中的每条记录，字段名以 JSON 解码后的文字比较（直接写出与
42	// Unicode 转义同名仍算重复）；限制只针对同一对象，不同记录各自携带同名字段
43	// 是正常结构，字符串值里提到字段名不算重复。
44	//
45	// JSON 字符串的原始内容必须能还原为合法 Unicode 文字：字符串中直接写入的
46	// 字节不是合法 UTF-8，或 \uXXXX 转义中出现未配对的高位/低位代理项（高位
47	// 代理项后没有紧跟低位代理项、孤立的低位代理项、两个高位代理项相连等），
48	// 整份文件都判为内容损坏——标准库会把这些内容静默替换成 U+FFFD，替换后的
49	// 编号或依据绝不能当成正常内容继续查询、核对或登记，哪怕问题只在一条已拒绝
50	// 免修的依据里或本次核对不涉及的课程名称里。检查只读不写：不替用户修补转义、
51	// 不删字符、不改动任何申请状态。合法文字不受影响：中文、直接写入的补充平面
52	// 字符、完整的高低代理项转义对、转义表达的控制字符，以及用户确实写入的
53	// “�”（U+FFFD）都按原样使用。
54	//
55	// 有效免修的依据校验与首次正常申请一致：任何状态为有效（approved）的免修，
56	// 其依据必须含有实际文字；依据为空，或全部由空白字符（空格、制表符、换行、
57	// 回车、全角空格 U+3000、不换行空格 U+00A0 等，允许混用）组成时，整份记录
58	// 按内容损坏拒绝读取，即使该要求另有通过修读也不例外。已拒绝申请的依据允许
59	// 为空或只有空白。检查只读不写：不会补填依据、不会改动免修状态，也不会修剪
60	// 含实际文字的依据中原有空白。
61	func Load(path string) (s *Store, existed bool, err error) {
62		f, err := os.Open(path)
63		if err != nil {
64			if errors.Is(err, os.ErrNotExist) {
65				return NewStore(), false, nil
66			}
67			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
68		}
69		defer f.Close()
70	
71		fi, err := f.Stat()
72		if err != nil {
73			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
74		}
75		if fi.Size() == 0 {
76			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
77		}
78	
79		raw, err := io.ReadAll(f)
80		if err != nil {
81			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
82		}
83	
84		// 先按原始字节检查 JSON 字符串能否还原为合法 Unicode 文字。标准库解码
85		// 会把非法 UTF-8 字节与未配对的高/低位代理项转义静默替换成 U+FFFD，
86		// 替换后的学生编号、课程名称或免修依据绝不能当成正常内容继续办理业务
87		// （两个本来不同的编号可能被替换成同一个），这样的文件整份判为内容
88		// 损坏，哪怕问题只在一条已拒绝免修的依据里或本次核对不涉及的课程名称
89		// 里。检查只读不写：不修补转义、不删字符、不改动申请状态。
90		if err := scanStringUnicode(raw); err != nil {
91			return nil, true, fmt.Errorf(
92				"记录文件 %s 内容损坏（包含无效的 Unicode 文字：%v），未做任何修改",
93				path, err)
94		}
95	
96		// 先在 token 流上检查同一 JSON 对象内是否出现重复字段名。标准库直接
97		// 解进结构体时会用后一个重复键静默覆盖前一个（例如课程写了两个
98		// credit，4 会被 9 悄悄顶替），这样的记录无法明确说明字段归属，必须
99		// 整份判为损坏，绝不能据此核对或办理。仅扫描第一份完整值，其后内容
100		// 仍由下方的“完整记录之后不得有多余内容”检查处理。
101		var dupErr *duplicateFieldError
102		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
103			return nil, true, fmt.Errorf(
104				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
105				path, dupErr.field)
106		}
107	
108		var data fileData
109		dec := json.NewDecoder(bytes.NewReader(raw))
110		dec.DisallowUnknownFields()
111		if err := dec.Decode(&data); err != nil {
112			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
113		}
114		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
115		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
116		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
117		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
118		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
119		// 片段。这些一律视为文件损坏。
120		var extra json.RawMessage
121		switch err := dec.Decode(&extra); {
122		case errors.Is(err, io.EOF):
123			// 唯一一份完整记录之后只有空白，符合格式。
124		case err == nil:
125			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
126		default:
127			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
128		}
129	
130		s = NewStore()
131		if err := s.loadData(&data); err != nil {
132			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
133		}
134		return s, true, nil
135	}
136	
137	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
138	func (s *Store) loadData(d *fileData) error {
139		if d.Version != recordVersion {
140			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
141		}
142	
143		// 课程
144		for _, c := range d.Courses {
145			if c == nil {
146				return errors.New("存在空的课程记录")
147			}
148			if c.ID == "" {
149				return errors.New("存在没有编号的课程")
150			}
151			if c.Name == "" {
152				return fmt.Errorf("课程 %s 没有名称", c.ID)
153			}
154			if c.Credit <= 0 {
155				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
156			}
157			if _, dup := s.courseByID[c.ID]; dup {
158				return fmt.Errorf("课程编号 %s 重复", c.ID)
159			}
160			s.courses = append(s.courses, c)
161			s.courseByID[c.ID] = c
162		}
163	
164		// 学生
165		for _, st := range d.Students {
166			if st == nil || st.ID == "" {
167				return errors.New("存在没有编号的学生记录")
168			}
169			if _, dup := s.studentByID[st.ID]; dup {
170				return fmt.Errorf("学生编号 %s 重复", st.ID)
171			}
172			s.students = append(s.students, st)
173			s.studentByID[st.ID] = st
174		}
175	
176		// 要求
177		for _, r := range d.Requirements {
178			if r == nil {
179				return errors.New("存在空的课程要求记录")
180			}
181			if r.StudentID == "" || r.ID == "" {
182				return errors.New("存在缺少学生编号或要求编号的课程要求")
183			}
184			if _, ok := s.studentByID[r.StudentID]; !ok {
185				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
186			}
187			if _, ok := s.courseByID[r.CourseID]; !ok {
188				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
189					r.StudentID, r.ID, r.CourseID)
190			}
191			key := reqKey(r.StudentID, r.ID)
192			if _, dup := s.reqByKey[key]; dup {
193				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
194			}
195			dk := dupKey(r.StudentID, r.CourseID)
196			if other, dup := s.reqByDup[dk]; dup {
197				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
198					r.StudentID, r.CourseID, other, r.ID)
199			}
200			s.requirements = append(s.requirements, r)
201			s.reqByKey[key] = r
202			s.reqByDup[dk] = r.ID
203		}
204	
205		// 修读
206		usedSeq := map[int]bool{}
207		for _, e := range d.Enrollments {
208			if e == nil {
209				return errors.New("存在空的修读记录")
210			}
211			if e.StudentID == "" || e.ID == "" {
212				return errors.New("存在缺少学生编号或修读编号的修读记录")
213			}
214			if _, ok := s.studentByID[e.StudentID]; !ok {
215				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
216			}
217			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
218			if r == nil {
219				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
220					e.StudentID, e.ID, e.ReqID)
221			}
222			if e.Term == "" {
223				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
224			}
225			switch e.Result {
226			case Enrolled, Passed, Failed:
227			default:
228				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
229			}
230			if e.Result == Enrolled {
231				if e.ResultSeq != 0 {
232					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
233				}
234			} else {
235				if e.ResultSeq <= 0 {
236					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
237				}
238				if usedSeq[e.ResultSeq] {
239					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
240				}
241				usedSeq[e.ResultSeq] = true
242			}
243			key := reqKey(e.StudentID, e.ID)
244			if _, dup := s.enrByKey[key]; dup {
245				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
246			}
247			s.enrollments = append(s.enrollments, e)
248			s.enrByKey[key] = e
249		}
250	
251		// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
252		// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
253		approvedReq := map[ownerKey]string{} // (student, req) -> waiverID
254		for _, w := range d.Waivers {
255			if w == nil {
256				return errors.New("存在空的免修记录")
257			}
258			if w.StudentID == "" || w.ID == "" {
259				return errors.New("存在缺少学生编号或免修编号的免修记录")
260			}
261			if _, ok := s.studentByID[w.StudentID]; !ok {
262				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
263			}
264			switch w.Status {
265			case WaiverApproved, WaiverRejected, WaiverRevoked:
266			default:
267				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
268			}
269			switch w.Status {
270			case WaiverApproved:
271				// 有效免修的依据校验与首次正常申请完全一致：依据必须含有实际
272				// 文字，空串或全部由空白字符（空格、制表符、换行、全角空格
273				// U+3000、不换行空格 U+00A0 等，含混用）组成都按内容损坏
274				// 拒绝整份记录——这样的“有效免修”无法有据可查，即使该要求
275				// 另有通过修读也不能放过。检查只读不写，绝不修剪或改写文件
276				// 中已保存的依据原文，也不把它降级成已拒绝/已撤销。
277				if blankBasis(w.Basis) {
278					return fmt.Errorf("学生 %s 的有效免修 %s 缺少依据（依据为空或全部为空白字符）",
279						w.StudentID, w.ID)
280				}
281				rk := reqKey(w.StudentID, w.ReqID)
282				if s.reqByKey[rk] == nil {
283					return fmt.Errorf("有效免修 %s 指向的要求 %s 不存在或不属于该学生", w.ID, w.ReqID)
284				}
285				if other, dup := approvedReq[rk]; dup {
286					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
287						w.StudentID, w.ReqID, other, w.ID)
288				}
289				approvedReq[rk] = w.ID
290			case WaiverRevoked:
291				// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
292				// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
293				// 该免修所属学生名下（同号要求只在其他学生名下不算），
294				// 原依据必须含有非空白内容（空白口径与有效免修一致，全角
295				// 空格、不换行空格等同样不算实际依据）。检查只读不写，
296				// 依据中有实际文字时原有空白一律保留，绝不为了通过检查
297				// 改写保存下来的材料内容。失效历史不参与有效免修的唯一
298				// 性限制。
299				if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
300					return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
301						w.StudentID, w.ID, w.ReqID)
302				}
303				if blankBasis(w.Basis) {
304					return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
305				}
306			}
307			key := reqKey(w.StudentID, w.ID)
308			if _, dup := s.waiverByKey[key]; dup {
309				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
310			}
311			s.waivers = append(s.waivers, w)
312			s.waiverByKey[key] = w
313		}
314	
315		if d.NextResultSeq < 0 {
316			return errors.New("结果提交序号计数器为负数")
317		}
318		for seq := range usedSeq {
319			if seq > d.NextResultSeq {
320				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
321			}
322		}
323		s.nextResultSeq = d.NextResultSeq
324		return nil
325	}
326	
327	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
328	// 避免写到一半时损坏原文件。
329	func (s *Store) Save(path string) (err error) {
330		data := fileData{
331			Version:       recordVersion,
332			Courses:       s.courses,
333			Students:      s.students,
334			Requirements:  s.requirements,
335			Enrollments:   s.enrollments,
336			Waivers:       s.waivers,
337			NextResultSeq: s.nextResultSeq,
338		}
339		buf, err := json.MarshalIndent(&data, "", "  ")
340		if err != nil {
341			return fmt.Errorf("无法序列化记录：%w", err)
342		}
343		buf = append(buf, '\n')
344	
345		dir := filepath.Dir(path)
346		if dir == "" {
347			dir = "."
348		}
349		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
350		if err != nil {
351			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
352		}
353		tmpName := tmp.Name()
354		defer func() {
355			if err != nil {
356				tmp.Close()
357				os.Remove(tmpName)
358			}
359		}()
360		if _, err = tmp.Write(buf); err != nil {
361			return fmt.Errorf("写入记录文件失败：%w", err)
362		}
363		if err = tmp.Sync(); err != nil {
364			return fmt.Errorf("写入记录文件失败：%w", err)
365		}
366		if err = tmp.Close(); err != nil {
367			return fmt.Errorf("写入记录文件失败：%w", err)
368		}
369		if err = os.Chmod(tmpName, 0o600); err != nil {
370			return fmt.Errorf("设置记录文件权限失败：%w", err)
371		}
372		if err = os.Rename(tmpName, path); err != nil {
373			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
374		}
375		return nil
376	}
377

