8	// 本文件从命令行入口回归“读取已有成绩记录时，两次独立的成绩提交不能共用
9	// 同一个结果提交序号”。这类冲突无法经正常提交流程落入文件（序号由计数器
10	// 递增分配），所以用例直接写出结构完整、可解析的记录文件，每条断言都重新
11	// 打开进程访问它：
12	//   - 两条不同的已提交修读共用同一个正整数序号时，无论两条都通过还是一条
13	//     未通过、无论它们属于同一学生的重复修读还是不同学生的独立修读，check、
14	//     show、list-courses 乃至写入类命令都沿用记录文件错误的退出码 2：不输出
15	//     任何业务结果，错误点名问题文件与重复的提交序号，原文件逐字节保留；
16	//   - 即使文件里另有一名完全正常的学生，也不能只读入正常部分继续核对；
17	//   - 修读编号相同、学期相同、记录在文件里的排列顺序都不是冲突依据；
18	//   - 合法记录中核对仍以提交序号较小的通过修读说明来源，多次通过只计一次
19	//     学分，更早提交的未通过保留在历史中但不成为来源；
20	//   - 多条尚未提交结果的选课共用序号 0 合法且不得学分；已提交序号允许跳号；
21	//     不同学生共用修读编号但序号不同时各自保留所属记录；只读访问不改文件。
22	
23	// assertSeqDupAccessRejected 用指定命令访问含重复提交序号的记录文件：
24	// 必须退出码 2、stdout 没有任何业务内容，stderr 点名问题文件、说明内容
25	// 损坏并给出重复的提交序号。调用方在全部访问后再统一比对原文件字节。
26	func assertSeqDupAccessRejected(t *testing.T, file string, args []string, seq, label string) {
27		t.Helper()
28		out, errText, code := runCLI(t, file, args...)
29		if code != exitFile {
30			t.Fatalf("%s：访问含重复提交序号的记录应退出码 %d，code=%d out=%q err=%q",
31				label, exitFile, code, out, errText)
32		}
33		if out != "" {
34			t.Fatalf("%s：整份记录损坏时不应输出任何业务结果，out=%q", label, out)
35		}
36		for _, want := range []string{
37			file,
38			"内容损坏",
39			"结果提交序号 " + seq + " 重复",
40		} {
41			if !strings.Contains(errText, want) {
42				t.Fatalf("%s：错误输出应点名问题文件并给出重复序号（缺 %q），err=%q",
43					label, want, errText)
44			}
45		}
46	}
