67	// 但同一学生同一学期的两条不同修读（两次通过）共用同一个正整数提交序号：
68	// 所有只读与写入类命令都必须退出码 2，不输出业务结果，错误点名文件与序号，
69	// 原文件逐字节保留。
70	func TestCLIDuplicateResultSeqRejectsAllCommands(t *testing.T) {
71		d := seqDupBase()
72		d.Enrollments = []diskEnr{
73			enrRecord("e1", "s1", "r1", "2024春", "passed", 3),
74			enrRecord("e2", "s1", "r1", "2024春", "passed", 3),
75		}
76		d.NextResultSeq = 3
77		file, raw := writeDiskRecord(t, d)
78	
79		// 只读核对：不能挑其中一条通过记录继续核对，也不能出现总学分。
80		assertSeqDupAccessRejected(t, file, []string{"check", "s1"}, "3", "check 当事学生")
81		// 历史查看同样拒绝。
