2	
3	import (
4		"fmt"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件为“读取已有成绩记录时，两次独立的成绩提交不能共用同一个结果提交
12	// 序号”这项既有行为提供回归保障。该冲突无法经正常提交流程落入文件（每次
13	// 提交都从递增计数器取号），因此全部用例直接构造记录文件，聚焦 Load 读取
14	// 历史这一路径：
15	//   - 文件完整可解析、学生/课程/要求齐全、修读归属与结果状态合法，只要两条
16	//     不同的修读（都已提交结果）共用同一个正整数序号，就整份判为损坏：
17	//     无论两条都通过还是一条未通过，无论它们是同一学生的重复修读、同一学生
18	//     不同要求的独立提交，还是不同学生的独立修读；即使文件里另有完全正常的
19	//     学生，也不能只读入正常部分继续核对；
20	//   - 修读编号相同、学期相同、记录在文件里的排列顺序，都不是冲突依据；
21	//   - 合法记录中两次通过按“提交序号较小者”说明来源，与文件排列、修读编号、
22	//     学期先后都无关；更早提交的未通过保留在历史中但不成为来源；
23	//   - 只有选课、尚未提交结果的修读一律使用序号 0，多条并存合法且不得学分；
24	//     已提交序号允许有间隔；不同学生共用修读编号但序号不同时各自保留归属。
25	//
26	// 所有合法用例都断言只读核对不改动原文件。
27	
28	// seqBaseRecord 构造结构完整、引用齐全的基础记录：学生 s1 的要求 r1 指向
29	// 4 学分课程 c1。修读与序号计数器由各用例自行补充。
30	func seqBaseRecord() *fileData {
31		return &fileData{
32			Version:      recordVersion,
33			Courses:      []*Course{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
34			Students:     []*Student{{ID: "s1"}},
35			Requirements: []*Requirement{{ID: "r1", StudentID: "s1", CourseID: "c1"}},
36		}
37	}
38	
39	// seqEnr 构造一条修读记录；result 为 enrolled 时 seq 传 0。
40	func seqEnr(id, student, req, term string, result Result, seq int) *Enrollment {
41		return &Enrollment{
42			ID: id, StudentID: student, ReqID: req, Term: term,
43			Result: result, ResultSeq: seq,
44		}
45	}
46	
47	// assertDupSeqRejected 是序号冲突用例的共同断言：Load 必须失败、文件标记为
48	// 已存在，错误点名问题文件、说明内容损坏并给出重复的提交序号，且原文件
49	// 字节完整保留、不会只加载其中一部分记录。
50	func assertDupSeqRejected(t *testing.T, d *fileData, seq int) {
51		t.Helper()
52		path, raw := writeRecord(t, d)
53		s, existed, err := Load(path)
54		if err == nil {
55			t.Fatalf("两条已提交修读共用序号 %d 时必须整份拒绝，却得到 store=%v", seq, s)
56		}
57		if s != nil {
58			t.Fatalf("序号冲突损坏整份记录时不得返回部分记录，得到 %v", s)
59		}
60		if !existed {
61			t.Fatalf("冲突记录应标记为文件已存在，existed=%v err=%v", existed, err)
62		}
63		msg := err.Error()
64		for _, want := range []string{
65			path,
66			"内容损坏",
67			fmt.Sprintf("结果提交序号 %d 重复", seq),
68		} {
69			if !strings.Contains(msg, want) {
70				t.Fatalf("错误信息应包含 %q（点名问题文件与重复序号），得到：%v", want, err)
71			}
72		}
73		got, readErr := os.ReadFile(path)
74		if readErr != nil {
75			t.Fatal(readErr)
76		}
77		if string(got) != string(raw) {
78			t.Fatalf("拒绝读取不得改写原文件\nwant=%q\n got=%q", raw, got)
79		}
80	}

